package dev.sunlit.bettersunlit.update;
import java.nio.file.*;import java.nio.channels.*;import java.util.*;import java.time.*;
/** Pre-start only; never stops a running server and only replaces this mod's canonical JAR. */
public final class ServerUpdate {
 public static void main(String[]args)throws Exception{if(!"server".equals(Build.CHANNEL))throw new IllegalStateException("Use the server branch artifact");if(args.length!=1)throw new IllegalArgumentException("Expected server directory");Path game=Path.of(args[0]).toRealPath();Path state=UpdateFiles.directory(game.resolve(".better-sunlit-update"));
  try(var channel=FileChannel.open(state.resolve("server-update.lock"),StandardOpenOption.CREATE,StandardOpenOption.WRITE);var lock=channel.tryLock()){
   if(lock==null)throw new java.io.IOException("Another updater is running");ensureStopped(state);recover(game,state);
   try{byte[] envelope=new SafeHttp().manifest();SignedRelease release=SignedRelease.verify(envelope,SignedRelease.publicKey());Path target=UpdateFiles.target(game);long current=UpdateFiles.installedBuild(target);Properties blocked=read(state.resolve("blocked.properties"));if(release.build()<=current||Long.toString(release.build()).equals(blocked.getProperty("build"))){System.out.println("[Better Sunlit] Installed build retained: "+current);return;}
    String old=UpdateFiles.sha(target);Path incoming=new SafeHttp().download(release,state.resolve("incoming"),n->{});Properties pending=new Properties();pending.setProperty("build",Long.toString(release.build()));pending.setProperty("newSha256",release.sha256());pending.setProperty("oldSha256",old);Path plan=state.resolve("server-pending.properties");UpdateFiles.writeProperties(plan,pending);
    try{ApplyUpdate.apply(game,incoming,release,old);}catch(Exception failure){if(UpdateFiles.sha(target).equals(old))Files.deleteIfExists(plan);throw failure;}System.out.println("[Better Sunlit] Verified server update installed: "+release.label());
   }catch(Exception e){System.err.println("[Better Sunlit] Update unavailable; retaining installed mod: "+e.getClass().getSimpleName()+": "+e.getMessage());}
  }
 }
 public static void ensureStopped(Path state)throws Exception{Properties running=read(state.resolve("server-running.properties"));if(running.isEmpty())return;long pid=Long.parseLong(running.getProperty("pid"));var h=ProcessHandle.of(pid);if(h.isPresent()&&h.get().isAlive()&&h.get().info().startInstant().map(i->i.toString().equals(running.getProperty("started"))).orElse(false))throw new java.io.IOException("Server is still running; no files changed");}
 public static void recover(Path game,Path state)throws Exception{Path plan=state.resolve("server-pending.properties");if(!Files.exists(plan))return;Properties pending=read(plan),health=read(state.resolve("server-health.properties"));if(pending.getProperty("build").equals(health.getProperty("build"))&&"ready".equals(health.getProperty("status"))){Files.delete(plan);return;}
  String old=pending.getProperty("oldSha256"),next=pending.getProperty("newSha256");if(old==null||!old.matches("[a-f0-9]{64}")||next==null||!next.matches("[a-f0-9]{64}"))throw new java.io.IOException("Invalid rollback metadata");Path target=UpdateFiles.target(game),backup=state.resolve("backups").resolve(old+"-"+SignedRelease.FILE);if(Files.isSymbolicLink(backup)||!UpdateFiles.sha(backup).equals(old)||!UpdateFiles.sha(target).equals(next))throw new java.io.IOException("Rollback files changed; manual review required");Path temp=state.resolve("rollback-"+UUID.randomUUID()+".jar");Files.copy(backup,temp);if(!UpdateFiles.sha(temp).equals(old))throw new java.io.IOException("Rollback checksum mismatch");UpdateFiles.replace(temp,target);Properties blocked=new Properties();blocked.setProperty("build",pending.getProperty("build"));UpdateFiles.writeProperties(state.resolve("blocked.properties"),blocked);Files.delete(plan);System.out.println("[Better Sunlit] Previous server build restored after incomplete startup");
 }
 static Properties read(Path p)throws Exception{if(Files.isSymbolicLink(p))throw new java.io.IOException("Linked updater state");return Files.isRegularFile(p)?SignedRelease.properties(Files.readAllBytes(p)):new Properties();}
}
